function(container, apiUrl, tables) {
  let selectedStores = new Set();
  let currentModel = null;
  let isProcessing = false;

  // ログ追加関数
  function addLog(message, type = 'info') {
    const logDisplay = container.querySelector('#log-display');
    const timestamp = new Date().toLocaleString();
    const logEntry = document.createElement('div');
    logEntry.className = `log-entry ${type}`;
    logEntry.innerHTML = `<span class="timestamp">[${timestamp}]</span><span class="message">${message}</span>`;
    logDisplay.appendChild(logEntry);
    logDisplay.scrollTop = logDisplay.scrollHeight;
  }

  // 店舗一覧の描画
  function renderStores() {
    const storeList = container.querySelector('#store-list');
    const stores = tables.find(t => t.tableName === '店舗マスタ')?.records || [];

    storeList.innerHTML = stores.map(store => `
      <label>
        <input type="checkbox" class="store-checkbox" data-store-id="${store.店舗ID}" value="${store.店舗ID}">
        ${store.店舗名} (${store.店舗コード})
      </label>
    `).join('');
  }

  // モデル一覧の描画
  function renderModels() {
    const modelSelect = container.querySelector('#select-model');
    // 需要予測結果テーブルから検証済みモデルを取得
    const predictions = tables.find(t => t.tableName === '需要予測結果')?.records || [];
    const models = [...new Set(predictions.map(p => p.予測モデルバージョン))].filter(Boolean);

    modelSelect.innerHTML = '<option value="">-- モデルを選択してください --</option>' +
      models.map(model => `<option value="${model}">モデル ${model}</option>`).join('');
  }

  // モデル詳細情報の表示
  function showModelDetails(modelVersion) {
    const detailsSection = container.querySelector('#model-details');
    const predictions = tables.find(t => t.tableName === '需要予測結果')?.records || [];
    const modelPredictions = predictions.filter(p => p.予測モデルバージョン === modelVersion);

    if (modelPredictions.length > 0) {
      const sample = modelPredictions[0];
      const accuracy = modelPredictions.filter(p => p.予測精度).reduce((sum, p) => sum + (p.予測精度 || 0), 0) / modelPredictions.length || 0;

      container.querySelector('#detail-name').textContent = `AI需要予測モデル v${modelVersion}`;
      container.querySelector('#detail-version').textContent = modelVersion;
      container.querySelector('#detail-accuracy').textContent = `${accuracy.toFixed(1)}%`;
      container.querySelector('#detail-created').textContent = new Date(sample.作成日時).toLocaleDateString();

      detailsSection.classList.remove('hidden');

      // 検証結果の更新
      updateValidationResults(modelVersion, accuracy);
    }
  }

  // 検証結果の更新
  function updateValidationResults(modelVersion, accuracy) {
    const validationResults = container.querySelector('#validation-results');
    const isValid = accuracy >= 80; // 80%以上を合格とする

    validationResults.innerHTML = `
      <div class="validation-item">
        <span class="status ${isValid ? 'success' : 'error'}">${isValid ? '検証合格' : '検証不合格'}</span>
        <span>予測精度: ${accuracy.toFixed(1)}% ${isValid ? '(適用可能)' : '(精度不足)'}</span>
      </div>
      <div class="validation-item">
        <span class="status success">データ整合性</span>
        <span>モデルデータの整合性チェック完了</span>
      </div>
    `;
  }

  // 影響範囲の更新
  function updateImpactAnalysis() {
    const storeCount = selectedStores.size;
    const products = tables.find(t => t.tableName === '商品マスタ')?.records || [];
    const categories = [...new Set(products.map(p => p.商品カテゴリID))].length;
    const estimatedMinutes = Math.max(5, storeCount * 2); // 店舗数 × 2分（最低5分）

    container.querySelector('#impact-stores').textContent = `${storeCount}店舗`;
    container.querySelector('#impact-categories').textContent = `${categories}カテゴリ`;
    container.querySelector('#impact-duration').textContent = `約${estimatedMinutes}分`;

    const warningElement = container.querySelector('#impact-warning');
    if (storeCount >= 10) {
      warningElement.classList.remove('hidden');
    } else {
      warningElement.classList.add('hidden');
    }
  }

  // 適用実行の有効性チェック
  function updateDeployButtonState() {
    const deployBtn = container.querySelector('#btn-deploy');
    const modelSelected = container.querySelector('#select-model').value;
    const storesSelected = selectedStores.size > 0;
    const startDateTime = container.querySelector('#input-start-datetime').value;
    const retentionDays = parseInt(container.querySelector('#input-retention-days').value);

    const isValid = modelSelected && storesSelected && startDateTime && retentionDays > 0 && !isProcessing;
    deployBtn.disabled = !isValid;
  }

  // 進捗表示の更新
  function updateProgress(percentage, message) {
    const progressFill = container.querySelector('#progress-fill');
    const progressText = container.querySelector('#progress-text');
    const progressSection = container.querySelector('#progress-section');

    progressSection.classList.remove('hidden');
    progressFill.style.width = `${percentage}%`;
    progressText.textContent = message;
  }

  // 適用処理のシミュレーション
  async function executeDeployment() {
    if (isProcessing) {
      addLog('既に適用処理が実行中です。処理完了後に再度実行してください。', 'error');
      return;
    }

    const modelVersion = container.querySelector('#select-model').value;
    const startDateTime = container.querySelector('#input-start-datetime').value;
    const retentionDays = parseInt(container.querySelector('#input-retention-days').value);
    const backupEnabled = container.querySelector('#backup-enabled').checked;

    // バリデーション
    if (!modelVersion) {
      addLog('適用対象のモデルが選択されていません', 'error');
      return;
    }

    if (selectedStores.size === 0) {
      addLog('店舗が選択されていない旨のエラーメッセージが表示されました', 'error');
      return;
    }

    if (new Date(startDateTime) < new Date()) {
      addLog('適用日時は現在日時以降を指定してください', 'error');
      return;
    }

    if (retentionDays <= 0) {
      addLog('保持期間に0日が設定されていることを警告します', 'warning');
      return;
    }

    isProcessing = true;
    updateDeployButtonState();

    try {
      addLog(`モデル ${modelVersion} の本番適用を開始します`, 'info');

      if (backupEnabled) {
        updateProgress(10, 'バックアップを作成中...');
        await new Promise(resolve => setTimeout(resolve, 1000));
        addLog('現行モデルのバックアップを作成しました', 'success');
      }

      updateProgress(30, 'モデルファイルを配信中...');
      await new Promise(resolve => setTimeout(resolve, 1500));
      addLog('モデルファイルの配信が完了しました', 'success');

      let progress = 30;
      const storeArray = Array.from(selectedStores);
      for (let i = 0; i < storeArray.length; i++) {
        const storeId = storeArray[i];
        const stores = tables.find(t => t.tableName === '店舗マスタ')?.records || [];
        const store = stores.find(s => s.店舗ID === storeId);

        progress = 30 + (i / storeArray.length) * 60;
        updateProgress(progress, `${store?.店舗名 || storeId} に適用中... (${i + 1}/${storeArray.length})`);

        await new Promise(resolve => setTimeout(resolve, 500));
        addLog(`${store?.店舗名 || storeId} への適用が完了しました`, 'success');
      }

      updateProgress(95, '最終検証中...');
      await new Promise(resolve => setTimeout(resolve, 1000));

      updateProgress(100, '適用完了');
      addLog(`全${selectedStores.size}店舗への適用が正常に完了しました`, 'success');
      addLog(`保持期間: ${retentionDays}日で設定されました`, 'info');

      // ロールバックボタンを有効化
      container.querySelector('#btn-rollback').disabled = false;

    } catch (error) {
      addLog(`適用処理中にエラーが発生しました: ${error.message}`, 'error');
      updateProgress(0, 'エラーが発生しました');
    } finally {
      isProcessing = false;
      updateDeployButtonState();
    }
  }

  // ロールバック処理
  async function executeRollback() {
    if (!container.querySelector('#btn-rollback').disabled) {
      if (!confirm('モデルをロールバックしますか？この操作は元に戻せません。')) {
        return;
      }

      addLog('ロールバック処理を開始します', 'info');
      updateProgress(0, 'ロールバック準備中...');

      try {
        updateProgress(25, 'バックアップモデルを復元中...');
        await new Promise(resolve => setTimeout(resolve, 1000));

        updateProgress(75, '各店舗に配信中...');
        await new Promise(resolve => setTimeout(resolve, 1500));

        updateProgress(100, 'ロールバック完了');
        addLog('ロールバック処理が正常に完了しました', 'success');

        container.querySelector('#btn-rollback').disabled = true;
      } catch (error) {
        addLog(`ロールバック処理中にエラーが発生しました: ${error.message}`, 'error');
      }
    } else {
      addLog('適用前のため、ロールバックできません', 'error');
    }
  }

  // 初期化
  renderStores();
  renderModels();

  // 現在日時を適用開始日時のデフォルトに設定
  const now = new Date();
  now.setMinutes(now.getMinutes() + 10); // 10分後をデフォルトに
  container.querySelector('#input-start-datetime').value = now.toISOString().slice(0, 16);

  // イベントリスナー
  container.querySelector('#select-model').addEventListener('change', (e) => {
    if (e.target.value) {
      currentModel = e.target.value;
      showModelDetails(e.target.value);
      addLog(`モデル ${e.target.value} が選択されました`, 'info');
    } else {
      container.querySelector('#model-details').classList.add('hidden');
      currentModel = null;
    }
    updateDeployButtonState();
  });

  container.querySelector('#select-all-stores').addEventListener('change', (e) => {
    const checkboxes = container.querySelectorAll('.store-checkbox');
    checkboxes.forEach(cb => {
      cb.checked = e.target.checked;
      if (e.target.checked) {
        selectedStores.add(cb.dataset.storeId);
      } else {
        selectedStores.delete(cb.dataset.storeId);
      }
    });

    container.querySelector('#selected-store-count').textContent = selectedStores.size;
    updateImpactAnalysis();
    updateDeployButtonState();

    if (e.target.checked) {
      addLog(`全店舗が選択されました (${selectedStores.size}店舗)`, 'info');
    } else {
      addLog('全店舗の選択が解除されました', 'info');
    }
  });

  container.addEventListener('change', (e) => {
    if (e.target.classList.contains('store-checkbox')) {
      if (e.target.checked) {
        selectedStores.add(e.target.dataset.storeId);
      } else {
        selectedStores.delete(e.target.dataset.storeId);
        container.querySelector('#select-all-stores').checked = false;
      }

      container.querySelector('#selected-store-count').textContent = selectedStores.size;
      updateImpactAnalysis();
      updateDeployButtonState();
    }
  });

  container.querySelector('#input-start-datetime').addEventListener('change', updateDeployButtonState);
  container.querySelector('#input-retention-days').addEventListener('input', updateDeployButtonState);
  container.querySelector('#backup-enabled').addEventListener('change', updateDeployButtonState);

  container.querySelector('#btn-deploy').addEventListener('click', executeDeployment);
  container.querySelector('#btn-rollback').addEventListener('click', executeRollback);

  // 初期状態の更新
  updateImpactAnalysis();
  updateDeployButtonState();
}
